export const filterOccupancyRecords = (
  state: OccupancyState,
  revision: number,
  input: RecordsRequest,
): RecordsResponse => {
  const occupancies = state.occupancies.filter(
    (record) =>
      (input.resourceId === undefined || record.occupancyRef.resourceId === input.resourceId) &&
      (input.kind === undefined || record.kind === input.kind) &&
      (input.state === undefined || record.state === input.state) &&
      (input.unitRef === undefined || refMatches(record.unitRef, input.unitRef)) &&
      (input.fromDate === undefined || record.endDate === null || record.endDate > input.fromDate) &&
      (input.toDate === undefined || record.startDate < input.toDate),
  );
  const unfiltered =
    input.resourceId === undefined &&
    input.unitRef === undefined &&
    input.kind === undefined &&
    input.state === undefined &&
    input.fromDate === undefined &&
    input.toDate === undefined;
  const visibleIds = new Set(occupancies.map((record) => record.occupancyRef.resourceId));
  return {
    bookingObservations:
      input.resourceId === undefined &&
      input.unitRef === undefined &&
      input.kind === undefined &&
      input.state === undefined &&
      input.fromDate === undefined &&
      input.toDate === undefined
        ? state.bookingObservations
        : state.bookingObservations.filter(
            (observation) =>
              observation.occupancyRef !== null &&
              occupancies.some(
                (record) =>
                  observation.occupancyRef !== null && refMatches(record.occupancyRef, observation.occupancyRef),
              ),
          ),
    // Unfiltered reads list every counterparty dossier, including prospects without a lease (S01).
    tenantDossiers: (state.tenantDossiers ?? []).filter(
      (dossier) =>
        unfiltered ||
        occupancies.some((record) => record.customerCounterpartyRef?.resourceId === dossier.counterpartyId),
    ),
    occupancyHistory: (state.occupancyHistory ?? []).filter((entry) => visibleIds.has(entry.occupancyId)),
    registrationSheets: (state.registrationSheets ?? []).filter((sheet) => visibleIds.has(sheet.occupancyId)),
    preparedNotices: (state.preparedNotices ?? []).filter((notice) => visibleIds.has(notice.occupancyId)),
    occupancies,
    revision,
  };
};
export type OccupancyPersistence = Readonly<{
  load: () => Effect.Effect<
    { readonly revision: number; readonly snapshot: OccupancyState },
    OccupancyPersistenceUnavailable
  >;
  save: (
    snapshot: OccupancyState,
    expectedRevision: number,
  ) => Effect.Effect<number, OccupancyPersistenceUnavailable | OccupancyConflict>;
}>;
export const persistenceService = (
  transaction: ScopedTransaction,
  scope: OperationalScope,
): Effect.Effect<OccupancyPersistence, OccupancyPersistenceUnavailable> => {
  if (scope.legalEntityId === undefined) {
    return Effect.fail(unavailable());
  }
  const { legalEntityId, tenantId } = scope;
  const scopeWhere = and(eq(occupancyState.tenantId, tenantId), eq(occupancyState.legalEntityId, legalEntityId));
  return Effect.succeed({
    load: () =>
      transaction
        .select()
        .from(occupancyState)
        .where(scopeWhere)
        .limit(1)
        .pipe(
          Effect.mapError(unavailable),
          Effect.flatMap(([row]) =>
            row === undefined
              ? Effect.succeed<{ readonly revision: number; readonly snapshot: OccupancyState }>({
                  revision: 0,
                  snapshot: { bookingObservations: [], occupancies: [] } satisfies OccupancyState,
                })
              : Schema.decodeEffect(OccupancyStateSchema)(row.snapshot).pipe(
                  Effect.mapError(unavailable),
                  Effect.map((snapshot) => ({ revision: row.revision, snapshot })),
                ),
          ),
        ),
    save: Effect.fn('OccupancyPersistence.save')(function* save(snapshot: OccupancyState, expectedRevision: number) {
      const [updated] = yield* transaction
        .update(occupancyState)
        .set({ revision: expectedRevision + 1, snapshot })
        .where(and(scopeWhere, eq(occupancyState.revision, expectedRevision)))
        .returning({ revision: occupancyState.revision })
        .pipe(Effect.mapError(unavailable));
      if (updated !== undefined) {
        return updated.revision;
      }
      if (expectedRevision !== 0) {
        return yield* conflict('stale_revision');
      }
      const [created] = yield* transaction
        .insert(occupancyState)
        .values({ legalEntityId, revision: 1, snapshot, tenantId })
        .onConflictDoNothing()
        .returning({ revision: occupancyState.revision })
        .pipe(Effect.mapError(unavailable));
      return created === undefined ? yield* conflict('stale_revision') : created.revision;
    }),
  });
};

